# This is a bounded coloring problem.

def find_coloring():
    # Try all assignments? 4^15 is too big (about 1 billion). Use backtracking.
    colors = [-1] * 15
    color_sizes = [0] * 4

    # Order vertices by degree descending for pruning
    order = sorted(range(15), key=lambda x: len(adj[x]), reverse=True)

    def backtrack(idx):
        if idx == 15:
            return True
        v = order[idx]
        # Try colors 0..3
