                continue
            # Check adjacency
            conflict = False
            for u in adj[v]:
                if colors[u] == c:
                    conflict = True
                    break
            if conflict:
                continue
            colors[v] = c
            color_sizes[c] += 1
            if backtrack(idx + 1):
                return True
            colors[v] = -1
            color_sizes[c] -= 1
        return False

    if backtrack(0):
        return colors
    else:
        return None

